'use strict';

// MODULES //

var tape = require( 'tape' );
var Complex64Array = require( '@stdlib/array/complex64' );
var icamax = require( './../lib/ndarray.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof icamax, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 4', function test( t ) {
	t.strictEqual( icamax.length, 4, 'returns expected value' );
	t.end();
});

tape( 'the function finds the index of the element with the maximum absolute value', function test( t ) {
	var expected;
	var icx;
	var x;

	x = new Complex64Array([
		0.1,  // 1
		-0.3, // 1
		0.5,  // 2
		-0.1, // 2
		-0.2, // 3
		0.6,  // 3
		-0.4, // 4
		0.9   // 4
	]);
	expected = 3;

	icx = icamax( 4, x, 1, 0 );
	t.strictEqual( icx, expected, 'returns expected value' );

	x = new Complex64Array([
		0.2,  // 1
		-0.6, // 1
		0.3,  // 2
		0.6,  // 2
		5.0,
		5.0
	]);
	expected = 1;

	icx = icamax( 2, x, 1, 0 );
	t.strictEqual( icx, expected, 'returns expected value' );

	t.end();
});

tape( 'if provided an `N` parameter less than `1`, the function returns `-1`', function test( t ) {
	var expected;
	var icx;
	var x;

	x = new Complex64Array([
		1.0,
		2.0,
		3.0,
		4.0
	]);
	expected = -1;

	icx = icamax( 0, x, 1, 0 );
	t.strictEqual( icx, expected, 'returns expected value' );

	t.end();
});

tape( 'if provided an `N` parameter equal to `1`, the function returns `0`', function test( t ) {
	var expected;
	var icx;
	var x;

	x = new Complex64Array([
		1.0,
		2.0,
		3.0,
		4.0
	]);
	expected = 0;

	icx = icamax( 1, x, 1, 1 );
	t.strictEqual( icx, expected, 'returns expected value' );

	t.end();
});

tape( 'the function supports accessing elements in reverse order', function test( t ) {
	var icx;
	var x;

	x = new Complex64Array( [ 3.0, -4.0, 1.0, 15.0, 4.0, 3.0 ] );

	icx = icamax( x.length, x, -1, x.length-1 );
	t.strictEqual( icx, 1, 'returns expected value' );

	icx = icamax( 2, x, -1, x.length-2 );
	t.strictEqual( icx, 0, 'returns expected value' );

	// eslint-disable-next-line max-len
	x = new Complex64Array( [ 0.1, 4.0, 999.0, 999.0, -0.3, 6.0, 999.0, 999.0, -0.5, 7.0, 999.0, 999.0, -0.1, 3.0 ] );
	icx = icamax( 4, x, -2, x.length-1 );
	t.strictEqual( icx, 1, 'returns expected value' );

	t.end();
});

tape( 'the function supports specifying a stride', function test( t ) {
	var expected;
	var icx;
	var x;

	x = new Complex64Array([
		0.1,  // 1
		4.0,  // 1
		-0.3,
		6.0,
		-0.5, // 2
		7.0,  // 2
		-0.1,
		3.0
	]);
	expected = 1;

	icx = icamax( 2, x, 2, 0 );
	t.strictEqual( icx, expected, 'returns expected value' );

	t.end();
});

tape( 'the function supports specifying an `x` offset', function test( t ) {
	var expected;
	var icx;
	var x;

	x = new Complex64Array([
		1.0,
		2.0,
		3.0,  // 0
		4.0,  // 0
		5.0,  // 1
		6.0,  // 1
		7.0,  // 2
		8.0   // 2
	]);
	expected = 2;

	icx = icamax( 3, x, 1, 1 );
	t.strictEqual( icx, expected, 'returns expected value' );

	t.end();
});

tape( 'the function supports complex access patterns', function test( t ) {
	var expected;
	var icx;
	var x;

	x = new Complex64Array([
		1.0,
		2.0,
		3.0,  // 0
		4.0,  // 0
		5.0,
		6.0,
		7.0,  // 1
		8.0   // 1
	]);
	expected = 1;

	icx = icamax( 2, x, 2, 1 );
	t.strictEqual( icx, expected, 'returns expected value' );

	t.end();
});
